import{H as e,ht as t,nt as n,tt as r}from"./chunks/framework.DiAOIirN.js";var i=JSON.parse(`{"title":"What is osm-mcp?","description":"","frontmatter":{},"headers":[],"relativePath":"guide/index.md","filePath":"guide/index.md","lastUpdated":1787084291000}`),a={name:`guide/index.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n(`<h1 id="what-is-osm-mcp" tabindex="-1">What is osm-mcp? <a class="header-anchor" href="#what-is-osm-mcp" aria-label="Permalink to “What is osm-mcp?”">​</a></h1><p><a href="https://www.openstreetmap.org" target="_blank" rel="noreferrer">OpenStreetMap</a> is the free, community-built map of the world, and a whole ecosystem of open services runs on top of it: geocoders, routing engines, POI databases. That is exactly what an assistant needs when you plan a trip — and exactly what it cannot reach without tools.</p><p><code>osm-mcp</code> is a <a href="https://modelcontextprotocol.io" target="_blank" rel="noreferrer">Model Context Protocol</a> server that connects the two. It exposes 11 read-only tools over the public OpenStreetMap services: geocoding (Nominatim and Photon), routing, travel-time matrices and stop-order optimization (OSRM), isochrones (Valhalla), POI search and details (Overpass), plus offline great-circle distance and openstreetmap.org link generation. <strong>No API key is required</strong> — an <a href="https://openrouteservice.org" target="_blank" rel="noreferrer">OpenRouteService</a> key can optionally switch the routing engine.</p><h2 id="what-you-can-do-with-it" tabindex="-1">What you can do with it <a class="header-anchor" href="#what-you-can-do-with-it" aria-label="Permalink to “What you can do with it”">​</a></h2><ul><li><strong>Turn names into places.</strong> &quot;Where exactly is the Louvre?&quot; &quot;What&#39;s at 49.6116, 6.1319?&quot; Photon is typo-tolerant, so &quot;Luvre&quot; works too.</li><li><strong>Plan real travel.</strong> &quot;How long is the walk from the hotel to the station?&quot; &quot;Compare these 5 hotels against these 3 sights by travel time.&quot; &quot;What order should I visit my six stops in?&quot;</li><li><strong>Explore an area.</strong> &quot;What can I reach in 15 minutes on foot?&quot; &quot;Vegan restaurants within 500 m of the cathedral?&quot; &quot;When is that museum open, and do they have a website?&quot;</li><li><strong>Coordinate people.</strong> &quot;Find a cafe that&#39;s fair for all three of us&quot; — the server searches venues around the midpoint and picks the one with the most balanced travel times.</li></ul><p>Every place input accepts either a name/address (geocoded automatically) or literal coordinates as <code>&quot;lat,lon&quot;</code>.</p><h2 id="why-another-osm-mcp-server" tabindex="-1">Why another OSM MCP server? <a class="header-anchor" href="#why-another-osm-mcp-server" aria-label="Permalink to “Why another OSM MCP server?”">​</a></h2><p>Two reasons, and the first one is a genuine correctness bug elsewhere:</p><ol><li><strong>Correct walking and cycling routes.</strong> The public OSRM demo servers ignore the profile segment inside the OSRM URL path and always return <strong>car</strong> routes unless the FOSSGIS <code>routed-foot</code> / <code>routed-bike</code> / <code>routed-car</code> path prefixes are used. Most existing OSM MCP servers get this wrong and silently return driving times for walking queries — a &quot;10 minute walk&quot; that is actually a 10 minute drive. This server uses the prefixes, and its live smoke test asserts that foot routes are much slower than car routes.</li><li><strong>Policy compliance built in.</strong> The public OSM services are shared community infrastructure with published usage policies. This server enforces them client-side: 1 request/second to Nominatim, Photon, OSRM, Valhalla and Overpass, a mandatory identifying User-Agent, response caching, at most 2 concurrent Overpass requests, and automatic failover to an Overpass mirror on 429/5xx instead of retry-hammering.</li></ol><p>There is also a third: optional <strong>Photon</strong> support. komoot&#39;s Photon geocoder is typo-tolerant and designed for interactive use — a better fit for LLM-driven lookups than sending every fuzzy guess to Nominatim.</p><h2 id="what-it-is-not" tabindex="-1">What it is not <a class="header-anchor" href="#what-it-is-not" aria-label="Permalink to “What it is not”">​</a></h2><p>It is not a map renderer — results are structured data and openstreetmap.org links, not images. It is not a live-traffic navigator: OSRM&#39;s travel times come from OpenStreetMap road data, not congestion feeds. And it is not a bulk-geocoding pipeline; the throttles that keep it inside the public usage policies make it deliberately slow for that. For heavy use, self-host the services and point the <code>*_BASE_URL</code> variables at them.</p><h2 id="how-it-fits-together" tabindex="-1">How it fits together <a class="header-anchor" href="#how-it-fits-together" aria-label="Permalink to “How it fits together”">​</a></h2><p>The server speaks <strong>stdio</strong> and never listens on a port. Your MCP client starts it as a child process; it holds no credentials by default and calls the public services over HTTPS with rate limiting and caching in between. There is no daemon to run and nothing to expose.</p><h2 id="next" tabindex="-1">Next <a class="header-anchor" href="#next" aria-label="Permalink to “Next”">​</a></h2><ul><li><a href="/guide/getting-started">Getting started</a> — install, first call</li><li><a href="/guide/clients">Connecting clients</a> — Claude Code, Claude Desktop, Codex, Docker</li><li><a href="/reference/tools">Tools reference</a> — all 11, with every parameter</li></ul>`,16)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};